-- SEMESTRE COMPLETO DE DEMONSTRAÇÃO (2026/2) — gerado por scripts/gerar_semestre_demo_sql.py a partir de app/demo_semestre.py.
-- ATENÇÃO: APAGA todos os dados (cursos, turmas, instrutores, salas, semestres, aulas, observações...) e carrega a demonstração.
-- MANTÉM: unidades, áreas, turnos e horários oficiais, configurações, perfis e usuários (os de instrutor perdem o vínculo antigo).
-- Requer as atualizações 0003 a 0020. Cole o arquivo inteiro no SQL Editor do Supabase e clique em Run.
-- Conteúdo: 2 unidades, 11 áreas, 16 cursos, 19 turmas (manhã, tarde, noite, sábado e PFP de dia inteiro), 30 instrutores, 19 salas e laboratórios,
-- 1075 aulas geradas pelo gerador de horários, semestre PUBLICADO, aulas até 15/10 marcadas como realizadas,
-- uma substituição, observações de instrutores, notificações do portal, instrutores mensalistas e horistas
-- e turnos de planejamento (PL) / projeto (PJ) dos mensalistas, instrutores BÁSICOS (só AIB e qualificações:
-- Rogério Lima, Tiago Barbosa, Wagner Prado e Sabrina Lopes), turmas 80-20 com a sexta EAD (HTC-LOG-21 e HTC-DDS-09),
-- turma de SÁBADO (QUA-INF-01, 09:00–13:00), turma PFP de dia inteiro (PFP-OPL-01, 08–12 e 13–17, a partir de 19/10),
-- UCs TRANSVERSAIS (INF-BAS, ADM-ATC), competências 'em partes' e
-- SOLICITAÇÕES de instrutores (2 aguardando o coordenador, 1 aprovada, 1 recusada).
-- CASOS PARA TESTAR CONFLITOS E AÇÕES:
--  * licença médica de Fábio Teixeira (26/10 a 06/11) com aulas marcadas → resolver por substituição;
--  * Laboratório de Automação e CLP (Beira Mar) em manutenção de 03/11 a 06/11 → trocar a sala;
--  * ponto facultativo no Porto em 28/10 com aulas → remarcar;
--  * turma nova HTC-ELT-1-14 (modular, 1º de 4 módulos; início 19/10) sem nenhuma aula → gerar horários só dela;
--  * turmas modulares HTC-MEC-2-08 e HTC-MCT-3-04: o código sobe a cada semestre até o último módulo;
--  * turma QUA-NRB-01 (NR-10 Básico, início 03/11) SEM INSTRUTOR POSSÍVEL: o único habilitado, Wagner Prado,
--    já dá aula em 9 de 10 turnos (teto de 90%) → a geração explica quem poderia e sugere mudanças;
--  * proposta de alteração 'Ajustes de novembro' (em edição) com aulas SEM INSTRUTOR (HTC-INS-02)
--    e aulas SEM SALA (QUA-DGR-01) → alocar na grade, validar e submeter.
-- Logins do portal do instrutor (senha portal@2026): juliana.prates, marcos.vieira, igor.batista, eduardo.salles.
-- Login de coordenação (perfil coordenador, senha portal@2026): coordenacao — aprova as solicitações dos instrutores.

-- 1) Limpeza (igual a limpar_dados_teste.sql)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM unidades WHERE codigo = 'BEIRA-MAR') OR NOT EXISTS (SELECT 1 FROM unidades WHERE codigo = 'PORTO') THEN
    RAISE EXCEPTION 'Unidades oficiais não encontradas: aplique antes as atualizações 0003 e 0004.';
  END IF;
  -- portal do instrutor (atualização 0005): os usuários de instrutor continuam, só perdem o vínculo
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'usuarios' AND column_name = 'instrutor_id') THEN
    EXECUTE 'UPDATE usuarios SET instrutor_id = NULL WHERE instrutor_id IS NOT NULL';
  END IF;
  EXECUTE 'TRUNCATE TABLE
    alocacao_recursos,
    alocacoes,
    ambiente_areas,
    ambientes,
    atividades,
    bloqueios,
    calendario_excecoes,
    calendarios,
    cenarios_planejamento,
    competencias_instrutores,
    cursos,
    deslocamentos_unidades,
    disponibilidade_ambientes,
    disponibilidade_instrutores,
    excecoes_autorizadas,
    execucoes_otimizacao,
    habilitacoes_instrutores,
    horarios_funcionamento,
    importacoes,
    instrutor_areas,
    instrutor_unidades,
    matrizes_curriculares,
    ocorrencias_validacao,
    recursos,
    recursos_ambientes,
    registros_decisao,
    resultados_otimizacao,
    setores,
    simulacoes_capacidade,
    tipos_ambiente,
    turma_uc,
    turmas,
    uc_prerequisitos,
    uc_recursos,
    uc_tipos_ambiente,
    unidades_curriculares,
    validacoes,
    versoes_planejamento'
    || CASE WHEN to_regclass('public.observacoes_instrutor') IS NOT NULL THEN ', observacoes_instrutor' ELSE '' END
    || CASE WHEN to_regclass('public.notificacoes') IS NOT NULL THEN ', notificacoes' ELSE '' END
    || CASE WHEN to_regclass('public.solicitacoes_instrutor') IS NOT NULL THEN ', solicitacoes_instrutor' ELSE '' END
    || CASE WHEN to_regclass('public.epis_turma') IS NOT NULL THEN ', epis_turma, epis_curso' ELSE '' END
    || CASE WHEN to_regclass('public.pdi_itens') IS NOT NULL THEN ', pdi_itens' ELSE '' END
    || CASE WHEN to_regclass('public.termos_horas') IS NOT NULL THEN ', termos_horas' ELSE '' END
    || ' RESTART IDENTITY';
  -- instrutores: DELETE (a tabela de usuários, que é mantida, aponta para ela)
  DELETE FROM instrutores;
  PERFORM setval(pg_get_serial_sequence('instrutores', 'id'), 1, false);
  -- usuários do portal do instrutor (perfil instrutor): sem os instrutores, não servem mais. O histórico de
  -- auditoria é mantido (com o nome de quem fez), só deixa de apontar para o usuário apagado.
  UPDATE historico_auditoria SET usuario_id = NULL WHERE usuario_id IN (SELECT id FROM usuarios WHERE perfil = 'instrutor');
  DELETE FROM usuarios WHERE perfil = 'instrutor';
  -- escopos de acesso que apontavam para cursos/turmas apagados ou unidades extras
  DELETE FROM permissoes WHERE escopo_tipo IN ('curso', 'turma')
     OR (escopo_tipo = 'unidade' AND escopo_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO')));
  DELETE FROM periodos_horarios WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM turnos WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM areas WHERE unidade_id NOT IN (SELECT id FROM unidades WHERE codigo IN ('BEIRA-MAR', 'PORTO'));
  DELETE FROM unidades WHERE codigo NOT IN ('BEIRA-MAR', 'PORTO');
  DELETE FROM configuracoes WHERE chave = 'worker_status';
END $$;

-- 2) Semestre de demonstração
DO $$
BEGIN
  IF to_regclass('public.notificacoes') IS NULL THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0005.sql (portal do instrutor, notificações e substituição).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM turnos WHERE codigo = 'N' AND hora_inicio = '18:30' AND hora_fim = '22:00') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0006.sql (turno da noite das 18:30 às 22:00).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'instrutores' AND column_name = 'modalidade') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0007.sql (modalidade do instrutor: mensalista/horista).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'instrutores' AND column_name = 'nivel') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0009.sql (nível do instrutor e dias EAD da turma).';
  END IF;
  IF to_regclass('public.solicitacoes_instrutor') IS NULL OR NOT EXISTS (SELECT 1 FROM turnos WHERE codigo = 'S') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0010.sql (coordenador, solicitações, UC transversal e turno de sábado).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM turnos WHERE codigo = 'I') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0011.sql (turno integral das turmas PFP).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'matrizes_curriculares' AND column_name = 'tipo_oferta') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0012.sql (PFP manhã e tarde, contagem em minutos e versões da matriz por oferta).';
  END IF;
  IF to_regclass('public.epis_turma') IS NULL THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0013.sql (EPIs por curso e controle por turma).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'cursos' AND column_name = 'dispensa_epi') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0014.sql (cursos que não precisam de EPI).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'turmas' AND column_name = 'modulos') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0015.sql (turmas modulares e reposição aos sábados).';
  END IF;
  IF to_regclass('public.pdi_itens') IS NULL THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0016.sql (PDI dos instrutores).';
  END IF;
  IF to_regclass('public.termos_horas') IS NULL THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0017.sql (termo de horas dos horistas).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'termos_horas' AND column_name = 'dias_semana') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0018.sql (dias do termo de horas).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'unidades_curriculares' AND column_name = 'modalidade') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0019.sql (UC presencial ou EAD).';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'termos_horas' AND column_name = 'agenda') THEN
    RAISE EXCEPTION 'Aplique antes atualizacao_0020.sql (termo de horas por dia e turno).';
  END IF;
  IF EXISTS (SELECT 1 FROM turmas) OR EXISTS (SELECT 1 FROM instrutores) THEN
    RAISE EXCEPTION 'A limpeza (parte 1) não foi executada: rode o arquivo inteiro.';
  END IF;
  -- bloqueios: 749
  PERFORM setval(pg_get_serial_sequence('bloqueios', 'id'), (SELECT max(id) FROM bloqueios));
  -- tipos_ambiente: 11
  PERFORM setval(pg_get_serial_sequence('tipos_ambiente', 'id'), (SELECT max(id) FROM tipos_ambiente));
  -- calendarios: 2
  PERFORM setval(pg_get_serial_sequence('calendarios', 'id'), (SELECT max(id) FROM calendarios));
  -- ambientes: 19
  PERFORM setval(pg_get_serial_sequence('ambientes', 'id'), (SELECT max(id) FROM ambientes));
  -- calendario_excecoes: 9
  PERFORM setval(pg_get_serial_sequence('calendario_excecoes', 'id'), (SELECT max(id) FROM calendario_excecoes));
  -- cursos: 16
  PERFORM setval(pg_get_serial_sequence('cursos', 'id'), (SELECT max(id) FROM cursos));
  -- instrutores: 30
  PERFORM setval(pg_get_serial_sequence('instrutores', 'id'), (SELECT max(id) FROM instrutores));
  -- ambiente_areas: 12
  -- disponibilidade_instrutores: 407
  PERFORM setval(pg_get_serial_sequence('disponibilidade_instrutores', 'id'), (SELECT max(id) FROM disponibilidade_instrutores));
  -- epis_curso: 20
  PERFORM setval(pg_get_serial_sequence('epis_curso', 'id'), (SELECT max(id) FROM epis_curso));
  -- habilitacoes_instrutores: 10
  PERFORM setval(pg_get_serial_sequence('habilitacoes_instrutores', 'id'), (SELECT max(id) FROM habilitacoes_instrutores));
  -- instrutor_areas: 16
  -- matrizes_curriculares: 16
  PERFORM setval(pg_get_serial_sequence('matrizes_curriculares', 'id'), (SELECT max(id) FROM matrizes_curriculares));
  -- notificacoes: 34
  PERFORM setval(pg_get_serial_sequence('notificacoes', 'id'), (SELECT max(id) FROM notificacoes));
  -- cenarios_planejamento: 2
  PERFORM setval(pg_get_serial_sequence('cenarios_planejamento', 'id'), (SELECT max(id) FROM cenarios_planejamento));
  -- pdi_itens: 3
  PERFORM setval(pg_get_serial_sequence('pdi_itens', 'id'), (SELECT max(id) FROM pdi_itens));
  -- solicitacoes_instrutor: 4
  PERFORM setval(pg_get_serial_sequence('solicitacoes_instrutor', 'id'), (SELECT max(id) FROM solicitacoes_instrutor));
  -- termos_horas: 39
  PERFORM setval(pg_get_serial_sequence('termos_horas', 'id'), (SELECT max(id) FROM termos_horas));
  -- unidades_curriculares: 47
  PERFORM setval(pg_get_serial_sequence('unidades_curriculares', 'id'), (SELECT max(id) FROM unidades_curriculares));
  -- competencias_instrutores: 87
  PERFORM setval(pg_get_serial_sequence('competencias_instrutores', 'id'), (SELECT max(id) FROM competencias_instrutores));
  -- execucoes_otimizacao: 1
  PERFORM setval(pg_get_serial_sequence('execucoes_otimizacao', 'id'), (SELECT max(id) FROM execucoes_otimizacao));
  -- registros_decisao: 2
  PERFORM setval(pg_get_serial_sequence('registros_decisao', 'id'), (SELECT max(id) FROM registros_decisao));
  -- uc_tipos_ambiente: 53
  -- validacoes: 6
  PERFORM setval(pg_get_serial_sequence('validacoes', 'id'), (SELECT max(id) FROM validacoes));
  -- ocorrencias_validacao: 562
  PERFORM setval(pg_get_serial_sequence('ocorrencias_validacao', 'id'), (SELECT max(id) FROM ocorrencias_validacao));
  -- resultados_otimizacao: 8
  PERFORM setval(pg_get_serial_sequence('resultados_otimizacao', 'id'), (SELECT max(id) FROM resultados_otimizacao));
  -- turmas: 19
  PERFORM setval(pg_get_serial_sequence('turmas', 'id'), (SELECT max(id) FROM turmas));
  -- epis_turma: 27
  PERFORM setval(pg_get_serial_sequence('epis_turma', 'id'), (SELECT max(id) FROM epis_turma));
  -- turma_uc: 55
  PERFORM setval(pg_get_serial_sequence('turma_uc', 'id'), (SELECT max(id) FROM turma_uc));
  -- atividades: 160
  PERFORM setval(pg_get_serial_sequence('atividades', 'id'), (SELECT max(id) FROM atividades));
  -- observacoes_instrutor: 3
  PERFORM setval(pg_get_serial_sequence('observacoes_instrutor', 'id'), (SELECT max(id) FROM observacoes_instrutor));
  -- alocacoes: 2150
  PERFORM setval(pg_get_serial_sequence('alocacoes', 'id'), (SELECT max(id) FROM alocacoes));
END $$;

-- 3) Acesso ao portal de alguns instrutores (a senha fica só como hash bcrypt)
